-- ============================================================
-- 003 · Corrección de duplicados en el andamiaje
--
-- Dos errores de la entrega anterior:
--
--   1. fusionarNodo() dejaba pasar campo_manual y firmas sin
--      fusionar, así que sus etiquetas imprimían el marcador literal
--      ({{tratamiento.piezas}}). Corregido en merge.js.
--
--   2. El bloque compartido diagnostico_plan repetía dos párrafos que
--      ya estaban en el cuerpo de 9 de las 18 plantillas, y añadía
--      rótulos "Diagnóstico:" / "Plan de tratamiento:" que el escaneo
--      original no tiene.
--
-- Este script arregla el segundo. Se puede ejecutar entero: las
-- plantillas están inactivas y sin revisar, así que sobrescribir su
-- composición no pierde trabajo de nadie.
--
-- Ninguna de estas tablas es consent_documentos, así que el trigger
-- de inmutabilidad no interviene.
-- ============================================================

begin;


-- Bloque compartido: sube a v2 y se ajusta al escaneo original.
update consent_bloques
   set contenido = '[{"tipo": "campo_manual", "lineas": 2}, {"tipo": "parrafo", "texto": "Para dicho diagnóstico me ha propuesto y presupuestado el siguiente plan de tratamiento:"}, {"tipo": "campo_manual", "etiqueta": "Piezas: {{tratamiento.piezas}}", "lineas": 3}, {"tipo": "parrafo", "texto": "En relación con el diagnóstico, el facultativo me ha explicado, y comprendo, que:"}]'::jsonb,
       version   = 2,
       notas     = 'Andamiaje entre el diagnóstico y el contenido clínico. Los dos párrafos de enlace viven AQUÍ y no deben repetirse en las plantillas. v2: se quitaron los rótulos, que el escaneo original no tiene, y se corrigió la duplicación en 9 de las 18 plantillas.'
 where codigo = 'diagnostico_plan';


-- Composición corregida de las plantillas afectadas.

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "titulo", "nivel": 2, "texto": "Consentimiento informado para"}, {"tipo": "titulo", "nivel": 2, "texto": "Blanqueamiento dental"}, {"tipo": "parrafo", "texto": "D/D* con N* de historia de años de edad, con domicilio en y con D.N.I. N*."}, {"tipo": "parrafo", "texto": "de años de edad, con domicilio en y Con D.N.I. N* en calidad de ( padre, madre, tutor) del/ de la paciente. DECLARO Que el Dr/ D* Me ha informado de uge se me va arealizar u tratamiento de blanqueamiento dental. Interno Sí/ No Externo Sí/ No en: El/ los diente/ es La arcada Dicho tratamiento consiste:"}, {"tipo": "lista", "items": ["Sí/ No En la aplicación de un gel con peróxido sobre la superficie de los dientes, previa protección de los tejidos blandos", "Sí/ No En la colocación de cubetas hechas a medida que le daremos en la consulta donde usted aplicará el agente blanqueador de forma domiciliaria", "Sí/ No En la combinación de las dos técnicas citadas previamente", "Sí/ No En la aplicación de un gel de peróxido en la cámara pulpar del diente/ es, previa protección de los tejidos blando y duros"]}, {"tipo": "parrafo", "texto": "Me han explicado que se me aclararán los dientes como mínimo de un tono, aunque si tengo bandas, éstas se me seguirán notando, aunque más claras. También se que si soy fumador/ a o tomo muchos alimentos o bebidas ricos en colorantes, se me volverán a oscurecer más rápido que no tengo éstos hábitos, de todos modos, me han explicado que los dientes se oscurecen de forma fisiológica por la edad. Si me han hecho un tratamiento con cubetas en casa, puedo repetir el tratamiento periódicamente, según indicación del dentista. Se me ha informado de que puedo tener sensibilidad al frío o a lo largo del tratamiento y que si esto me sucede debo suspender el tratamiento y acudir a la consulta. También se"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'BLANQUEAMIENTO' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "me ha informado del riego de resorción radicular que algunas veces pueden producir estos tratamientos, aunque dicho riesgo es muy bajo. He entendido todo lo que se me ha explicado, he hecho todas las preguntas que me han surgido y se me han aclarado adecuadamente. De todos modos puedo revocar el consentimiento que ahora firmo en cualquier momento. Firmado: DENTISTA: PACIENTE:"}, {"tipo": "parrafo", "texto": "D/D* con N* de historia de años de edad, con domicilio en y con D.N.I. N*."}, {"tipo": "parrafo", "texto": "de años de edad, con domicilio en y Con D.N.I. N* en calidad de ( padre, madre, tutor) del/ de la paciente."}, {"tipo": "parrafo", "texto": "REVOCO El consentimiento prestado en fecha y no deseo proseguir el tratamiento, que doy en esta fecha por finalizado. Firmado: DENTISTA: PACIENTE:"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'BLANQUEAMIENTO_2' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Nombre del Paciente: Fecha:"}, {"tipo": "titulo", "nivel": 2, "texto": "Diagnostico"}, {"tipo": "parrafo", "texto": "Se requieren las iniciales"}, {"tipo": "parrafo", "texto": "del paciente Las carillas dentales (en ocasiones llamadas carillas de porcelana o láminas dentales de porcelana) son delgadas, hechas a la medida y con material del color del diente. Estas carillas se adhieren a la parte delantera de los dientes, cambiando su color, forma, tamaño y longitud. El tratamiento de carillas para los dientes delanteros requiere eliminar menos estructura dental que la preparación para una corona completa. Sin embargo, el proceso es irreversible porque parte del esmalte del diente debe ser eliminado para proveer el espacio adecuado para fijar con cemento la cubierta. La restauración para una carilla requiere de dos fases: 1) la preparación del diente, y la toma una impresión para enviarla al laboratorio, y 2) el ajuste y cementación de la carilla una vez que la estética y la función han sido verificadas."}, {"tipo": "parrafo", "texto": "Entre otros, los beneficios de las carillas son los siguientes: Una carilla típicamente se usa para dientes que están decolorados o manchados ya sea por un tratamiento de endodoncia, por manchas de tetracicleno u otras drogas, fluoruro excesivo, o por la presencia de largas tapaduras de resina que han decolorado al diente. Las carillas pueden proteger a los dientes que se han desgastado, despostillado o roto. Una carilla puede ser usada para propósitos estéticos al reparar dientes que están mal alineados, que no están uniformes o que tienen una forma irregular, así como para cerrar espacios entre dientes."}, {"tipo": "parrafo", "texto": "Entre otros, los riesgos de las carillas son los siguientes: Entiendo que preparar un diente para una carilla consiste en eliminar el esmalte de la superficie del diente involucrado. Esta preparación puede irritar el tejido nervioso (llamado pulpa) en el centro del diente, dejando al diente sensible al calor, al frío o a la presión. Los dientes sensibles pueden requerir tratamiento adicional, incluido el tratamiento de endodoncia. Entiendo que el mantener mi boca abierta durante el tratamiento puede causar que mi mandíbula se sienta tiesa y adolorida temporalmente y puede ser difícil para mi abrir mucho la boca por algunos días. Esto puede ser ocasionalmente una indicación de un problema adicional. Debo notificar a su consultorio si tengo esta, u otras, preocupación o duda. Entiendo que las carillas típicamente no pueden ser reparadas si se despostillas o si se rompen. En ese caso es posible que se conceda una corona completa. Entiendo que las carillas pueden no igualar exactamente el color de mis otros dientes. También el color de la carilla no puede ser alterado una vez que ésta ha sido colocada. Entiendo que a pesar de que no es probable, las carillas pueden desprenderse y caerse. Para minimizar el riesgo de que esto suceda, no debo de morder mis uñas, lápices, hielo u otros objetos duros, y tampoco debo de poner presión en mis dientes. También el rechinar los dientes puede causar que la carilla se desprenda."}, {"tipo": "parrafo", "texto": "Entiendo que la carilla va a quedar cerca de la línea de mi encía, que es un área que tiende a la irritación, infección y/o deterioro. El cepillado apropiado, el uso de hilo dental, una dieta saludable y limpiezas profesionales, son algunas de las medidas preventivas esenciales para ayudar a controlar estos problemas. Entiendo que existe el riesgo de aspirar (inhalar) o tragar la carilla durante el tratamiento. Entiendo que puedo recibir una anestesia local y/u otro medicamento. En raros casos los pacientes pueden presentar reacciones a la anestesia, que pueden requerir atención médica de emergencia, o pueden experimentar una reducción en su habilidad para tragar. Esto incrementa la posibilidad normal de tragar objetos durante el tratamiento. Dependiendo de la anestesia y de los medicamentos administrados, es posible que necesite a un conductor designado que me lleve a casa. La inyección, en casos muy raros, puede provocar daño temporal o permanente a los nervios. Entiendo que todos los medicamentos tienen en potencial de presentar riesgos, efectos secundarios e interacciones con otros medicamentos. Por lo tanto es fundamental que le informe a mi dentista sobre todos los medicamentos que estoy tomando actualmente, los cuales son: Entiendo que se hará todo esfuerzo razonable para asegurar el éxito de mi tratamiento."}, {"tipo": "parrafo", "texto": "Entre otras las consecuencias si no se administra el tratamiento son las siguientes: Entiendo que si no se realiza el tratamiento, yo podría seguir experimentando los síntomas que pueden incrementarse en su severidad y que la apariencia cosmética de mis dientes puede continuar deteriorándose."}, {"tipo": "parrafo", "texto": "Entre otras, las alternativas a las carillas son las siguientes: Entiendo que, dependiendo de la razón por la cuál haya optado por una carilla, las alternativas pueden existir, incluido el tratamiento de ortodoncia para alineación de los dientes. He preguntado a mi dentista sobre estas alternativas y sobre sus costos. Mis preguntas sobre los procedimientos, sus riesgos, costos y beneficios, han sido respondidas a mi satisfacción. Alternativas discutidas:"}, {"tipo": "parrafo", "texto": "Nadie me ha garantizado que el propuesto tratamiento, curará o mejorará la condición (0 condiciones) mencionada"}, {"tipo": "parrafo", "texto": "1 Se me ha dado la oportunidad de formular preguntas y doy mi consentimiento para el tratamiento propuesto tal y como se describe anteriormente. ] Meniego a dar mi consentimiento para el tratamiento propuesto tal y como se describe arriba y entiendo las consecuencias potenciales asociadas con esta negativa."}, {"tipo": "parrafo", "texto": "Firma del paciente — Fecha —"}, {"tipo": "parrafo", "texto": "Doy fe de que he examinado los riesgos, beneficios, consecuencias y alternativas de las coronas y carillas dentales"}, {"tipo": "parrafo", "texto": "con (nombre del paciente) quien ha tenido oportunidad de hacer preguntas, y en mi"}, {"tipo": "parrafo", "texto": "opinión, mi paciente entiende lo que se le ha explicado."}, {"tipo": "parrafo", "texto": "Firma del dentista Fecha"}, {"tipo": "parrafo", "texto": "Firma del testigo Fecha"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'CARILLAS' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Los procedimientos propios de la cirugía oral van dirigidos básicamente a la extracción de cualquier tipo de tejidos (dentarios, óseos, gingivales, cuerpos extraños e incluso tejidos tumorales) situados en la zona bucodentaria o a la remodelación de estos tejidos para mejorar su función. Ello implica la invasión y manipulación mecánica del medio interno del organismo. Dentro de estos procedimientos se incluyen las extracciones dentarias simples o complejas, extracción de tejidos granulomatosos o neoplásicos situados en encía, hueso o mucosa oral, remodelación ósea, etc, realizados mediante distintos procedimientos."}, {"tipo": "titulo", "nivel": 2, "texto": "Limitaciones y riesgos"}, {"tipo": "parrafo", "texto": "El/la paciente ha sido informado/a y conoce los riesgos estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico difícilmente previsibles, anestesias prolongadas, daños locales por la punción, excepcionalmente dolores neuropáticos, etc", "Riesgo de inflamación y dolor en la zona tratada debido al procedimiento quirúrgico", "Riesgo de hemorragia y aparición de hematomas en la zona o áreas adyacentes", "Riesgo de dehiscencia (separación) de las suturas empleadas", "Riesgo de que se produzcan pequeños daños en las zonas próximas a las tratadas debido a la manipulación y separación de tejidos propios de la cirugía", "Riesgo de alveolitis tras una exodoncia, consistente en una infección en el alvéolo que produce un dolor muy intenso y es rebelde a los tratamientos. Se produce por despegamiento o pérdida prematura del coágulo de sangre que debería ocupar el alvéolo, lo que permite la entrada de saliva en el mismo y su colonización por microbios. Es más frecuente y severa en fumadores", "Riesgo importante de sobreinfección de las heridas quirúrgicas por los gérmenes bucales", "Riesgo de pérdida de sensibilidad, temporal o no, en la zona tratada por los daños producidos a las pequeñas terminaciones nerviosas", "Riesgo de limitación o imposibilidad de abrir la boca durante un tiempo variable (trismo), debido a la inflamación postquirúrgica, y molestias en la articulación témporo-mandibular, por la posición de boca abierta forzadamente que se debe adoptar durante la cirugía, principalmente en la extracción de los cordales, incluidos o no", "Respecto a la extracción de terceros molares, puede existir riesgo de lesión de las estructuras nerviosas cercanas: nervio dentario inferior y nervio lingual. La posición de dichos nervios tiene variaciones anatómicas que en ocasiones los acerca tanto al tercer molar que pueden ser lesionados durante su"]}, {"tipo": "parrafo", "texto": "extracción. En la mayoría de las ocasiones la posición exacta del nervio no puede determinarse con exactitud mediante las pruebas radiológicas habituales. La lesión suele provocar una disminución de la: sensibilidad, en ocasiones total, de determinadas zonas linguales (en caso de lesión del nervio lingual) o cercanas al labio (en caso de lesión del nervio dentario inferior). Estas alteraciones de la sensibilidad suelen remitir en unos meses, pero en ocasiones son permanentes. Muy raramente la lesión de los troncos y terminaciones nerviosas puede provocar dolores de tipo neuropático, habitualmente limitados en el tiempo, pero que en situaciones excepcionales pueden ser permanentes. Debido a la zona donde se efectuará el tratamiento quirúrgico, se podrán producir además los siguientes riesgos y complicaciones: \" Asimismo el St/STa ……… W..meremrereenere eee eee reneereereseee..POL SUS EsPeciales condiciones personales olc c yen PE preseniar riesgos añiadidos consistentes en: El paciente también ha sido informado de que debe seguir los consejos y pautas de tratamiento dados por el profesional y que deberá consultar cualquier eventualidad que ocurra y que le parezca anormal. Debe además acudir a la revisión de la zona tratada y a retirar los puntos de sutura si procede en el plazo que se la ha indicado, y siempre que tenga cualquier tipo de molestia o duda sobre el tratamiento."}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'CIRUGIAORAL' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Los dientes pueden destruirse por caries y por desgastes crónicos (atrición, abrasión, erosión y abfracción)."}, {"tipo": "lista", "items": ["Lacaries es una enfermedad causada por microbios que se nutren de los restos alimenticios acumulados en las bocas con higiene deficiente. De estos restos, los más importantes son los carbohidratos (sobre todo, azúcares refinados), a partir de los cuales se producen ácidos que desmineralizan los dientes y los hacen presa fácil de otros microbios que posteriormente degradan y destruyen la estructura debilitada. Las caries son reversibles mientras la superficie dentaria se mantenga lisa y regular, pero una vez alterada, avanza irremediablemente", "Los desgastes dentarios crónicos pueden deberse a:", "Causas mecánicas, responsables de la atrición fisiológica (desgaste por la masticación), de la atrición patológica (desgaste por el apretamiento o el rechinamiento de los dientes) y de la abrasión (desgaste por fuerzas no masticadoras, como, por ejemplo, el cepillado dental intempestivo)", "Causas químicas, como la erosión o desgaste por acción de ácidos (el jugo gástrico en los grandes vomitadores, cuales son las personas bulímicas) o el abuso de cítricos y bebidas carbonatadas", "Causas desconocidas, como la abfracción o milólisis, consistente en unas lesiones a manera de sacabocados, progresivas e inevitables, en los cuellos, que se relacionan, al parecer, con debilidad del esmalte y con alteraciones en la oclusión o \"engranaje\" de los dientes"]}, {"tipo": "parrafo", "texto": "Una restauración es una reconstrucción de una porción dentaria destruida, fracturada, desgastada o afectada irreversiblemente por patología, previa terapéutica de la misma y \"preparación\" dentaria apropiada."}, {"tipo": "parrafo", "texto": "Según su amplitud o extensión, las restauraciones también se dividen en obturaciones o reconstrucciones."}, {"tipo": "parrafo", "texto": "Atendiendo al procedimiento de realización y otras características, la restauraciones se dividen en:"}, {"tipo": "lista", "items": ["Obturaciones (popularmente, \"empastes\") realizados con distintos materiales y procedimientos, en los que los materiales se colocan en el diente en estado blando y se endurecen y conforman en la boca; pueden ser de amalgama (metálicas), de resina compuesta o \"composite\" (material estético) o de algún tipo de cemento", "ionómero de vidrio por ejemplo)", "Incrustaciones, consistentes en pequeñas piezas rígidas (metálicas, de porcelana o de resina compuesta) sustitutivas de las partes perdidas, prefabricadas a medida de la cavidad dentaria preparada por el dentista y cementadas o adheridas a los tejidos dentarios remanentes; se clasifican en inlays, onlays y overlays, según su situación y extensión", "Carillas o frentes laminados estéticos: son unas láminas muy delgadas de porcelana o de resina, bien prefabricadas o bien fabricadas a medida, que se adhieren a la superficie labial o anterior de los dientes para restaurar sus defectos anatómicos o estéticos", "Coronas o fundas coronarias; son coberturas completas o parciales de la superficie de los dientes. Se fabrican a medida, después de que el dentista realice la preparación dentaria (tallado de muñones, que es el desgaste adecuado los dientes) y obtenga un molde del muñón o eje dentario de sujeción, y las cemente o adhiera a"]}, {"tipo": "parrafo", "texto": "dicho muñón. Pueden ser de metal, porcelana, metal-porcelana, resina o metal-resina."}, {"tipo": "lista", "items": ["También se consideran restauraciones, ciertos medios accesorios o complementarios de retención (pernos, pins, ó etc), que tienen por función reforzar el diente debilitado y ayudar a la sujeción de la parte reconstruida del diente"]}, {"tipo": "parrafo", "texto": "Las principales finalidades de este tipo de restauraciones son detener la progresión de la enfermedad cariosa y evitar"}, {"tipo": "parrafo", "texto": "que siga la destrucción del diente hasta su definitiva pérdida; y devolverle al diente su forma natural (anatómica), su"}, {"tipo": "parrafo", "texto": "función y, si es posible, su estética, mediante el reemplazo de los tejidos perdidos o enfermos e irrecuperables."}, {"tipo": "titulo", "nivel": 2, "texto": "Limitaciones y riesgos"}, {"tipo": "parrafo", "texto": "Ella paciente ha sido informado/a y conoce los riesgos estadísticamente frecuentes que puede comportar este \" tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico dificilmente previsibles, anestesias prolongadas, daños locales por la punción, excepcionalmente dolores neuropáticos, etc", "Riesgo de sensibilidad, dolor u otras alteraciones irreversibles en el complejo dentino-pulpar, en caso de obturaciones profundas, que implicarían la necesidad de realizar la endodoncia del diente afectado", "Riesgo de pequeñas molestias al masticar, generalmente debidas a pequeños contactos previos o excesivos de la restauración con el diente antagonista, que puede pasar inadvertido tras la colocación por el efecto de la anestesia. Habitualmente desaparecen espontáneamente o se solucionan con muy pequeños retoques o ajustes", "Riesgo de inflamación crónica de la encía en restauraciones muy subgingivales debido a que resulta dificil la higiene oral diaria. Siendo la única solución quirúrgica: consistente en quitar encía y hueso para alargar la corona o parte visible del diente y dejar expuesto el margen de la restauración", "Riesgo de alteración en el color del diente y, a veces, tinciones de la encía (tatuajes), producidas por las obturaciones metálicas, en las zonas adyacentes a la restauración", "Respecto a las obturaciones dentocoloreadas, puede existir riesgo de sufrir cambios de color con el tiempo, además de su tendencia a mancharse más que los dientes naturales", "Riesgo de ingestión, o incluso aspiración, de pequeños restos de material de obturación sobrante", "Riesgo de pequeños daños en los tejidos blandos adyacentes a la zona de trabajo (encía, carrillo, lengua, etc) debidos al uso del instrumental de trabajo, instrumentos separadores o clamps para sujetar el dique de goma", "En caso de tratamientos estéticos existirá siempre el riesgo de no cumplir con las expectativas del paciente por motivos difícilmente evitables: inexistencia de tonos de color exactos, decoloraciones o tinciones no corregibles, etc"]}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'CONSERVADORA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "titulo", "nivel": 2, "texto": "Documento de consentimiento informado para"}, {"tipo": "titulo", "nivel": 2, "texto": "Cirugia de elevacion sinusal"}, {"tipo": "parrafo", "texto": "En cumplimiento de la Ley 41/2002, básica reguladora de la autonomía del paciente y de derechos y"}, {"tipo": "parrafo", "texto": "obligaciones en materia de información y documentación clínica, se le presenta para su firma el"}, {"tipo": "parrafo", "texto": "siguiente documento:"}, {"tipo": "parrafo", "texto": "paciente (en caso de menores o incapacitados consignar el nombre y DNI del padre, madre o tutor ), ha sido informado/a por"}, {"tipo": "parrafo", "texto": "de. Sobre los procedimientos clínicos de cirugía de elevación sinusal, que"}, {"tipo": "parrafo", "texto": "constan en el plan del tratamiento propuesto."}, {"tipo": "parrafo", "texto": "Los procedimientos de cirugía de elevación sinusal van dirigidos básicamente a interponer entre el"}, {"tipo": "parrafo", "texto": "seno maxilar y la cavidad oral una cantidad de hueso suficiente que nos permita insertar, con"}, {"tipo": "parrafo", "texto": "mayores posibilidades de éxito, implantes osteointegrables. La técnica consiste en acceder al seno"}, {"tipo": "parrafo", "texto": "maxilar a través de una incisión realizada en la cavidad oral y una ventana practicada en el hueso"}, {"tipo": "parrafo", "texto": "maxilar. Una vez en el seno se procede a despegar y levantar su mucosa y a introducir, si procede,"}, {"tipo": "parrafo", "texto": "algún material de relleno óseo. En el mismo acto quirúrgico se pueden colocar implantes"}, {"tipo": "parrafo", "texto": "osteointegrables o no. Muy raramente se precisan procedimientos de fijación u osteosíntesis"}, {"tipo": "parrafo", "texto": "externos como placas, mallas o tornillos. Posteriormente se sutura la zona."}, {"tipo": "parrafo", "texto": "Este procedimiento está indicado para el problema que tiene el/la paciente, consistente en una"}, {"tipo": "parrafo", "texto": "insuficiente cantidad de hueso en la zona del seno maxilar para permitir la inserción de implantes"}, {"tipo": "parrafo", "texto": "Se han sopesado y descartado por distintos motivos, de los que ha sido informado/a, otros"}, {"tipo": "parrafo", "texto": "procedimientos terapéuticos alternativos como:"}, {"tipo": "parrafo", "texto": "El/la paciente ha sido informado/a y conoce los riesgos estadísticamente frecuentes que puede"}, {"tipo": "parrafo", "texto": "comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico difícilmente previsibles, anestesias prolongadas, daños locales por la punción, etc", "Riesgo de inflamación y dolor en la zona tratada debido al procedimiento quirúrgico", "Riesgo de hemorragia y aparición de hematomas en la zona o áreas adyacentes", "Riesgo de dehiscencia (separación) de las suturas empleadas", "Riesgo de que se produzcan pequeños daños en las zonas próximas a las tratadas debido a la manipulación y separación de tejidos propios de la cirugía, en especial desgarros de la mucosa sinusal y rotura de la cortical ósea (que obligaría a utilizar otros procedimientos de cierre del seno maxilar)", "Riesgo de sobreinfección de las heridas quirúrgicas por los gérmenes bucales", "Riesgo de pérdida de sensibilidad, temporal o no, en la zona tratada por los daños producidos a las pequeñas terminaciones nerviosas", "Complicaciones infrecuentes propias del procedimiento quirúrgico de elevación sinusal: aparición de sinusitis aguda o crónica (que en ocasiones puede obligar a la reintervención), comunicación orosinusal (que sería indicación de nueva cirugía), alergia a los materiales de relleno utilizados no povenientes del paciente (hueso liofilizado, hidroxiapatita de origen animal, etc.) y colección hemática persistente en seno maxilar (que obligaría a su drenaje)", "Riesgos y complicaciones debidas a los procedimientos de injertos de hueso autólogos (del propio paciente) en caso de utilizarse. La zona donante de hueso puede sufrir complicaciones propias de la extracción de dicho hueso: dolor, inflamación, etc"]}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'ELEVACION' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "lista", "items": ["Patología dentaria destructiva de las piezas {{tratamiento.piezas}}.", "Otras situaciones que originen dolor o hipersensibilidad pulpar en las piezas {{tratamiento.piezas}}."]}, {"tipo": "lista", "items": ["Endodoncia de las piezas {{tratamiento.piezas}}."]}, {"tipo": "parrafo", "texto": "La finalidad del tratamiento de conductos es poder conservar funcionalmente un diente cuya pulpa está irreversiblemente dañada; de otro modo, debería ser extraído para eliminar el dolor y/o la infección del diente, del hueso y de los tejidos perirradiculares."}, {"tipo": "parrafo", "texto": "Los procedimientos propios de la endodoncia van dirigidos al tratamiento de las patologías del complejo dentino-pulpar (conocido vulgarmente como el nervio del diente) intentando conservar al máximo las estructuras dentarias y su función. Dentro de estos tratamientos se incluyen básicamente las pulpectomías (eliminación de todo el tejido pulpar posible, vital o no, seguida por una desinfección, instrumentación y relleno u obturación del sistema cavitario intradentario donde se encontraba dicha pulpa) y las pulpotomías (eliminación parcial superficial del tejido pulpar seguida de una cobertura de la herida a la entrada de la raíz con sustancias medicamentosas). Este tratamiento precisará ser completado en el futuro con toda probabilidad. Ambos tratamientos pueden ser realizados mediante distintos procedimientos (manuales y/o mecánicos) y diversos materiales y técnicas de sellado o relleno."}, {"tipo": "parrafo", "texto": "Cuando sea necesario realizar una endodoncia en un diente inmaduro cuyo ápice no está completamente cerrado será necesario realizar previamente lo que se denomina apicogénesis y apicoformación, tratamientos que consisten en la inducción del cierre del conducto radicular mediante diferentes materiales. Una vez que dicho cierre se haya producido habrá que proceder a realizar la endodoncia de la pieza."}, {"tipo": "parrafo", "texto": "La única alternativa terapéutica existente a la endodoncia suele ser la extracción dentaria."}, {"tipo": "titulo", "texto": "Limitaciones y riesgos", "nivel": 2}, {"tipo": "parrafo", "texto": "El/la paciente ha sido informado/a y conoce las limitaciones y los riesgos estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico difícilmente previsibles, anestesias prolongadas, daños locales por la punción, excepcionalmente dolores neuropáticos, etc.", "Riesgo de fractura de la corona del diente endodonciado por la debilitación producida en el mismo por la endodoncia. Este suceso podría conllevar la necesidad de tratamiento protésico o extracción dental.", "Riesgo de fracturas o fisuras radiculares del diente endodonciado, por múltiples motivos difícilmente previsibles, y que conllevarían en la mayoría de los casos la pérdida del diente.", "Riesgo de la existencia de anomalías anatómicas en los conductos radiculares, difícilmente detectables por procedimientos radiológicos, que impidan la correcta limpieza y sellado de dicho conducto (conductos laterales, deltas apicales, calcificaciones, curvaturas extremas, etc.).", "Riesgo de no encontrar algún conducto radicular para su limpieza y sellado, sobre todo en dientes polirradiculares o con conductos accesorios. En caso de producirse esta eventualidad será debidamente informado.", "Riesgo de fractura del material empleado (limas, léntulos, material rotatorio, etc.) dentro del conducto radicular, hecho que no tiene por qué empeorar el pronóstico de la endodoncia. En cualquier caso el paciente será informado de este suceso y sus posibles consecuencias en caso de que se produzca.", "Riesgo de paso a los tejidos periapicales (los que rodean la raíz del diente) de parte de los productos utilizados para la limpieza y desinfección de los conductos radiculares (habitualmente productos que contienen hipoclorito sódico), o de los utilizados para sellar dichos conductos. Este paso accidental de estas sustancias puede provocar molestias postoperatorias, en ocasiones, importantes.", "Riesgo de ingestión, o más difícilmente aspiración, del pequeño material utilizado si no es posible o es muy dificultosa la utilización del dique de goma.", "Riesgo de pequeños daños en los tejidos blandos adyacentes al diente debido al uso del instrumental (clamps del dique de goma, instrumentos de corte de gutapercha, etc.).", "Riesgo de aparición de sensibilidad, dolor e incluso inflamación tras un procedimiento endodóncico correcto. Para la posible aparición de este supuesto, siempre imprevisible, se le darán las oportunas instrucciones.", "En el caso de que previamente a la endodoncia existiese un granuloma o quiste periapical, existe el riesgo de que no desaparezca tras ella y se precise cirugía periapical (técnica quirúrgica para llegar a la infección desde la encía) para su completa eliminación.", "Riesgo de alteración del color del diente endodonciado por la pérdida de vitalidad, difícilmente evitable y prevenible, y que implicaría la necesidad de tratamientos estéticos o protésicos."]}, {"tipo": "titulo", "texto": "Expectativas infundadas frecuentes", "nivel": 2}, {"tipo": "lista", "items": ["En la endodoncia, como en cualquier tratamiento odontológico, no existe «garantía de por vida». En condiciones normales, el éxito es del orden del 95 % (algo menor en los dientes infectados, en los que tienen anormalidades anatómicas).", "Si la endodoncia no produce la curación deseada, puede estar indicada la repetición del tratamiento de conductos o complementarlo con un tratamiento quirúrgico (apicectomía). En estos casos, las expectativas de éxito descienden a dos tercios de los casos. De no lograrse tampoco la curación, la indicación odontológica es la extracción (exodoncia)."]}, {"tipo": "titulo", "texto": "Advertencias importantes", "nivel": 2}, {"tipo": "lista", "items": ["Las diversas modalidades de tratamiento endodóncico no incluyen la reconstrucción o restauración del diente, que deberá realizarse posteriormente, como tratamiento aparte; admite diversas alternativas (principalmente, obturación —o empaste—, o refuerzos intrarradiculares y corona protésica), que ofrecen diferente resistencia a las fuerzas masticatorias.", "La existencia de una endodoncia no previene que ese diente padezca caries, enfermedad periodontal, o cualquier otra afección dentaria, que son patología distinta y ajena al tratamiento de conductos."]}]}, {"ref": "riesgos_personalizados"}, {"nodos": [{"tipo": "parrafo", "texto": "El paciente también ha sido informado de que los dientes endodonciados, debido a su debilidad, las fuerzas que soportan y al paso del tiempo, podrán sufrir deterioros (fisuras, fracturas, etc.) que harán necesario su revisión periódica. Para detectar estas circunstancias es informado que debe someterse a revisiones periódicas, en ningún caso espaciadas más de un año, y siempre que tenga cualquier tipo de molestia o duda sobre el tratamiento."}]}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'ENDODONCIA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Los trastornos disfuncionales témporo-mandibulares o cráneo-mandibulares son un conjunto muy variado de patologías de la ATM (articulación temporo-mandíbular), o de sus estructuras asociadas, que afectan a la función normal de dicha articulación y/o producen dolor. Las causas de estas patologías son muy variadas, algunas son congénitas (como la hiperlaxitud ligamentaría) y otras son adquiridas (como la ausencia de dientes que puede provocar problemas en la oclusión dentaria, o traumatismos directos o indirectos en la zona). Los principales factores de riesgo son:"}, {"tipo": "lista", "items": ["Ausencia de piezas dentarias no rehabilitadas mediante prótesis bucodental", "Hábitos nocivos como el \"apretamiento dentario\" o el bruxismo (apretamiento y rechinamiento dentarios)"]}, {"tipo": "parrafo", "texto": "La gran mayoría de los trastornos disfuncionales de la ATM no curan, y el tratamiento está encaminado a controlar la sintomatología y evitar en lo posible la progresión del proceso. Al ser un trastorno crónico, los tratamientos y las visitas de control, también lo son. Los trastomos disfuncionales de la ATM son de muy variada etiología, y por tanto, los tratamientos también son muy diferentes. No obstante hay fases de estos tratamientos que son comunes:"}, {"tipo": "lista", "items": ["Equilibrar la oclusión dentaria, rehabilitando los dientes perdidos y ajustando la oclusión", "Proteger la ATM mediante el uso de \"férulas oclusales o de descarga\"", "Uso de fármacos antiinflamatorios y/o relajantes musculares en las fases agudas", "El tratamiento quirúrgico de la ATM es excepcional, y está reservado para casos muy graves"]}, {"tipo": "parrafo", "texto": "En ocasiones los problemas disfuncionales de la ATM tienen como origen o factor de agravamiento un problema psicológico (estrés, ansiedad, etc.). En estos casos se precisaría también un tratamiento psicológico asociado al odontológico. La finalidad del tratamiento consiste en aliviar la sintomatología de la disfunción de la articulación témporo-mandíbular e intentar detener su progresión. Para ello los objetivos son:"}, {"tipo": "lista", "items": ["Aliviar las fuerzas oclusales anómalas generadas en el aparato estomatognático y que afectan a la"]}, {"tipo": "parrafo", "texto": "ATM 0 sus estructuras asociadas (musculatura masticatoria, ligamentos, etc.). —"}, {"tipo": "lista", "items": ["Reposicionar, en ocasiones, la mandíbula para lograr una mejor posición en reposo de la ATM"]}, {"tipo": "parrafo", "texto": "Las \"férulas de descarga\" son productos sanitarios a medida. Esto implica que se precisará tomar impresiones de sus arcadas dentarias y diversos registros de la relación existente entre ellas. Precisan ser renovadas periódicamente, y ello por dos motivos: soportan fuerzas oclusales potentes que deterioran los"}, {"tipo": "parrafo", "texto": "materiales, y además se deben adaptar a los cambios producidos en el aparato masticatorio."}, {"tipo": "titulo", "nivel": 2, "texto": "Limitaciones y riesgos"}, {"tipo": "lista", "items": ["Riesgo de no habituarse a la \"férulas de descarga\", lo que suele requerir un tiempo y, en ocasiones, retoques de las partes de la férula que irriten los tejidos blandos de la boca", "Riesgo de presentar alergia a los materiales acrílicos, provocando una irritación alérgica en los tejidos blandos bucales (labios,encías, lengua, etc.)", "Riesgo de irritación mecánica, ingestión o aspiración de algún fragmento desprendido de la férula, si se produce la rotura de la férula"]}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'FERULA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "titulo", "nivel": 2, "texto": "Modelo de consentimiento informado"}, {"tipo": "titulo", "nivel": 2, "texto": "Implantes dentales"}, {"tipo": "parrafo", "texto": "Lugar y fecha Usted tiene derecho a conocer el procedimiento al que va a ser sometido y las complicaciones mas frecuentes que ocurren. Este documento intenta explicarle todas estas cuestiones, léalo atentamente y consulte todas las dudas que se le planteen. Le recordamos que por imperativo legal, tendrá que firmar, usted o su representante legal, el consentimiento informado para que pueda realizarle dicho procedimiento. El/la que suscribe,DNI N¡,con domicilio en calle otorgo mi consentimiento a la colocación de un implante dental fija en el/los elemento/s N* propuesto por el/la Dr. Asimismo declaro conocer que el objeto del tratamiento es reponer dientes perdidos. Se que alternativamente podría recurrir a prótesis convencionales, de menor costo, pero lo descarto por los beneficios que se pueden obtener con la técnica implantológica. El procedimiento se lleva a cabo en dos fases, una primera en la que se fijan tornillos o laminas al hueso mediante la realización con fresas de un lecho artificial, y una segunda (pasados varios meses) cuando el hueso y el tornillo esta integrados, se coloca un pilar sobre ellos para recibir posteriormente los aditamentos protésicos. ANESTESIA: la intervención requiere anestesia local cuyos riesgos son:"}, {"tipo": "lista", "items": ["Ulceración de la mucosa, dolor,", "Limitaciones en el movimiento de la apertura de la boca (que puede requerir tratamiento ulterior)", "Baja de tensión, sensación de mareo", "Menos frecuentemente: alergias, urticaria, dermatitis de contacto,, edema angioneurotico, fibrilación ventricular, que pueden requerir tratamiento ulterior"]}, {"tipo": "titulo", "nivel": 2, "texto": "Material convenido"}, {"tipo": "titulo", "nivel": 2, "texto": "Limitaciones"}, {"tipo": "parrafo", "texto": "Aunque la técnica se realice correctamente, existe la posibilidad de fracaso por razones biológicas, que puede requerir la repetición de la intervención"}, {"tipo": "titulo", "nivel": 2, "texto": "Riesgos tipicos"}, {"tipo": "lista", "items": ["Procesos edematosos, inflamación, hematomas, dolor, laceraciones en la mucosa del labio o mejilla, o en lengua que no dependen de la técnica ni de su correcta realización", "Posibilidad de lesionar el seno maxilar,", "Sinusitis, que deba ser tratada por un especialista competente;", "Lesiones de tipo nervioso, por afectar terminaciones nerviosas o nervios próximos que generara perdida de sensibilidad en labios, mentón, lengua o encía — según cual sea el nervio afectado", "Generalmente la perdida de sensibilidad es transitoria, aunque puede llegar a ser permanente,", "Comunicación con las fosas nasales y lesionar raíces de dientes adyacentes, que pueden requerir tratamiento posterior", "Excepcionalmente, la fractura maxilar que requiera tratamiento posterior"]}, {"tipo": "parrafo", "texto": "Firma del Paciente o Representante Firma del Profesional Firma Jefe de Equipo Aclaración Aclaración Aclaracion"}, {"tipo": "titulo", "nivel": 2, "texto": "Riesgos personalizados"}, {"tipo": "parrafo", "texto": "Además de los riesgos antes descriptos, por mi circunstancias especiales hay que esperar los siguientes riesgos:"}, {"tipo": "titulo", "nivel": 2, "texto": "Indicaciones"}, {"tipo": "lista", "items": ["Esimportante mantener una correcta higiene bucal luego del tratamiento", "La colocación del implante no constituye el acto final del tratamiento, sino que es necesario visitar periódicamente al facultativo a y realizar un seguimiento cada meses a los fines de detectar precozmente y tratar con mejor pronostico la aparición de cualquier complicación", "Acudir a una consulta inmediata siempre que aparezcan ulceraciones, alguna anormalidad o movilidad del implante"]}, {"tipo": "parrafo", "texto": "He comprendido todas las explicaciones que se me han facilitado en lenguaje claro y sencillo, he podido realizar todas las observaciones y se me han aclarado todas las dudas; por lo que estoy completamente de acuerdo con lo consignado en esta formula de consentimiento. Me comprometo a regresar a la próxima consulta el día A / Hora;"}, {"tipo": "lista", "items": ["Firmadel Paciente o Representante — FirmadelProfesional — FirmaJefedeEquipo"]}, {"tipo": "parrafo", "texto": "Aclaración Aclaración Aclaración"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'IMPLANTES' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "titulo", "nivel": 2, "texto": "Documento de consentimiento informado para la"}, {"tipo": "titulo", "nivel": 2, "texto": "Realizacion de tratamiento con injertos conectivos"}, {"tipo": "parrafo", "texto": "En cumplimiento de la Ley 41/2002, básica reguladora de la autonomía del paciente y de derechos y obligaciones en materia de información y documentación clínica, se le presenta para su firma el siguiente documento: D/D2 con DNI como paciente (en caso de menores o incapacitados consignar el nombre y DNI del padre, madre o tutor ), ha sido informado/a por el Dr/Dra Col n* de. Sobre los procedimientos clínicos de injertos de tejido conectivo, que constan en el plan de tratamiento que previamente he aceptado, y entiendo el propósito y naturaleza del tratamiento con injertos de tejido conectivo, así como también entiendo la necesidad de emplear un procedimiento quirúrgico para colocar el injerto. Los procedimientos propios de la implantología oral van dirigidos básicamente a la sustitución de alguna/as raíces dentarias perdidas para que sirvan de soporte a algún tipo de rehabilitación protésica. Ello implica la invasión y manipulación mecánica del medio interno del organismo: incisión y despegamiento gingival, preparación en el hueso, colocación del implante y sutura. Según el tipo de implante y la situación del paciente existen variaciones técnicas que pueden significar tener que dejar en reposo el implante durante un tiempo. Posteriormente se vuelve a acceder al implante a través de la encía y se acoplan los accesorios protésicos necesarios para la confección y colocación de la prótesis. Este procedimiento está indicado para el problema que tiene el/la paciente, consistente en:"}, {"tipo": "parrafo", "texto": "He recibido información de los posibles riesgos y complicaciones involucradas en el procedimiento quirúrgico, uso de medicamentos y anestesia. Algunas de estas complicaciones incluyen dolor, inflamaciones, infecciones, decoloraciones y mordeduras. La duración de estos fenómenos no está determinada, pudiendo ser irreversible, también puede ocurrir daño a dientes preexistentes, fracturas óseas, penetración en cavidades, reacciones alérgicas a medicamentos, dolores de cabeza, dolores referidos, etc."}, {"tipo": "parrafo", "texto": "He sido informado de que no hay ningún método para predecir la completa integración de los injertos, y me han explicado que en caso de no integrarse adecuadamente deben extraerse, por lo que no existen garantías en los resultados que se pueden obtener con estos tratamientos."}, {"tipo": "parrafo", "texto": "He sido informado de los riesgos atribuidos al uso del tabaco y sus derivados, que reducen considerablemente la tasa de éxitos en los tratamientos con injertos."}, {"tipo": "parrafo", "texto": "Acepto la realización de injertos de tejidos conectivos procedentes de bancos de tejidos humanos, utilización de biomateriales y, en general, cualquier técnica quirúrgica que sea necesaria para el éxito de mi tratamiento."}, {"tipo": "parrafo", "texto": "Me han informado de que el plan de tratamiento podría sufrir variación en función de las incidencias quirúrgicas de mi caso, péro de todas formas, se adaptaría lo más posible a lo previamente diseñado."}, {"tipo": "parrafo", "texto": "Debido a la zona donde se efectuará el tratamiento quirúrgico, se podrán producir además los siguientes riesgos y complicaciones:"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'INJERTOS' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Los procedimientos propios de la odontopediatría van dirigidos al tratamiento de las patologías dentales"}, {"tipo": "lista", "items": ["caries, fracturas, hipoplasias, etc) intentando conservar al máximo las estructuras dentarias y su función, y asegurar en-lo posible el correcto recambio dentario. Dentro de estos procedimientos se incluyen: las extracciones, las obturaciones (empastes) realizados con distintos materiales, las pulpotomías", "eliminación parcial de la pulpa dentaria-vulgarmente conocida como nervio-), los mantenedores de espacio, etc"]}, {"tipo": "parrafo", "texto": "Se han sopesado y descartado por distintos motivos de los que ha sido informado/a otros procedimientos terapéuticos alternativos COMO ……… e0e0ee0e0e0neeee D El/la paciente ha sido informado/a y conoce los riesgos estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico difícilmente previsibles, anestesias prolongadas, daños locales por la punción, excepcionalmente dolores neuropáticos, etc", "Riesgo de sensibilidad, dolor u otras alteraciones irreversibles en el complejo dentino-pulpar, en caso de obturaciones profundas, que implicarían la necesidad de realizar la endodoncia del diente afectado", "Riesgo de ingestión, o incluso aspiración, de pequeños restos de material de obturación sobrante", "Riesgo de pequeños daños en los tejidos blandos adyacentes a la zona de trabajo (encía, carrillo, lengua, etc) debidos al uso del instrumental de trabajo, instrumentos separadores o clamps para separar el dique de goma. Este riesgo será mayor en caso de niños poco colaboradores", "En caso de tratamientos estéticos existirá siempre el riesgo de no cumplir con las expectativas del paciente por motivos difícilmente evitables: inexistencia de tonos de color exactos, decoloraciones o tinciones no corregibles, etc", "Riesgo de que los tratamientos que afecten a la pulpa dentaria (vulgarmente conocida como nervio) produzcan molestias a veces aparatosas que requerirían tratamiento", "Riesgo de que se despeguen ciertos dispositivos utilizados en odontopediatría como mantenedores de espacio o coronas metálicas. En ese caso habría que acudir a consulta tan pronto como sea posible", "En caso de que sea preciso utilizar medicación relajante existe el riesgo, muy infrecuente, de reacciones adversas a dicha medicación. En caso de ser utilizada se debe estar muy pendiente del niño hasta su completa recuperación", "Riesgo de que el tratamiento no pueda ser realizado si el niño no es mínimamente colaborador"]}, {"tipo": "parrafo", "texto": "En este caso, dentista y padres deberán decidir la actuación a elegir. Asimismo el niño/a ……… — ……… r..0rm0m eeec eeeeeese==-..PO SUS ESPeCiales condiciones personales"}, {"tipo": "lista", "items": ["puede presentar riesgos añadidos consistentes en:"]}, {"tipo": "parrafo", "texto": "El paciente y sus padres o tutores también han sido informados de que los trabajos de odontopediatría, debido a las fuerzas que soportan y al paso del tiempo, sufrirán deterioros (fisuras, desprendimientos, despegamientos, etc) que harán necesario su renovación periódica hasta que se produzca el recambio dentario. Para prevenir estas circunstancias se informa que debe someterse a revisiones periódicas, en ningún caso espaciadas más de seis meses, y siempre que tenga cualquier tipo de molestia o duda sobre el tratamiento."}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'ODONTOPEDIATRIA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "y Ortopedia Dentofacial"}, {"tipo": "titulo", "nivel": 2, "texto": "Documento de consentimiento informado para"}, {"tipo": "titulo", "nivel": 2, "texto": "Ortodoncia propuesto por la sociedad española"}, {"tipo": "titulo", "nivel": 2, "texto": "De ortodoncia"}, {"tipo": "parrafo", "texto": "En cumplimiento de la Ley 41/2002, básica reguladora de la autonomía del paciente y de derechos y obligaciones en materia de información y documentación clínica, se le presenta para su firma el siguiente documento: 1D DD )1 UN D)| UNO como paciente (en caso de menores o incapacitados consignar el nombre y DNI del padre, madre 0 tutor ……… —..—.. nRe ), DE sido miormado''a por el DeDIS === — — aa o E aE col P rnnnnniiee dErnnnrnnnnnnneee... SODITE los procedimientos clínicos de ortodoncia, que constan en el plan de tratamiento que previamente he aceptado. Los procedimientos propios de la ortodoncia van dirigidos al tratamiento de anomalías en la colocación dentaria o en el desarrollo óseo que pueden producir alteraciones en la función masticatoria y en la estética, principalmente. El propósito principal de la ortodoncia es mejorar la salud bucal al conseguir un alineamiento correcto de los dientes así como una relación intermaxilar adecuada con una oclusión normal. Los tratamientos de ortodoncia también pueden formar parte de tratamientos más complejos y asociarse a tratamientos periodontales o de prótesis dental. En ocasiones la ortodoncia se realiza como preparación de las arcadas para tratamientos de cirugía ortognática (que realizará bajo su responsabilidad el cirujano máxilofacial).La ortodoncia incluye muchos posibles procedimientos. Éstos se podrían clasificar, de forma muy básica, en procedimientos de aparatología fija (vestibular o lingual), aparatología removible, aparatos ortopédicos bucofaciales, y todas sus posibles combinaciones. Todos los aparatos pero en especial los removibles requieren una adecuada colaboración en su uso y cuidados para obtener el resultado previsto. Si el paciente no lo usa el tiempo prescrito, el resultado y la duración no serán los previstos. Este procedimiento está indicado para el problema que tiene el/ la paciente, consistente"}, {"tipo": "parrafo", "texto": "Se han sopesado y descartado por distintos motivos de los que ha sido informado/a otros procedimientos terapéuticos alternativos COMO ……… e2e00000 000"}, {"tipo": "parrafo", "texto": "El/la paciente ha sido informado/a y conoce los riesgos que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgo de sensibilidad dentaria debido a las fuerzas ejercidas sobre los dientes o maxilares", "Riesgo de que se suelten partes de la aparatología fija (brackets, bandas, arcos, etc.) debido a las fuerzas masticatorias. Ante esta situación hay que consultar con el profesional", "Riesgo de ingestión, o incluso aspiración, de los materiales empleados en ortodoncia fija (brackets, etc.) que se hubiesen podido despegar completamente", "Riesgo de pequeñas molestias dolorosas de los dientes y la irritación de encías, labios, mejillas y lengua (llagas). Estas molestias suelen ser iniciales y remiten espontáneamente en unos días", "Riesgo de alergia a los materiales empleados que podría provocar su retirada y un eventual cambio en el plan de tratamiento", "Riesgo de que una deficiente higiene facilite la aparición de manchas blancas permanentes (descalcificaciones), caries dental o gingivitis (encías inflamadas)"]}, {"tipo": "parrafo", "texto": "Se me ha explicado con toda claridad que durante el tratamiento debo de extremar las medidas higiénicas y evitar la ingesta frecuente de productos muy azucarados."}, {"tipo": "lista", "items": ["En caso de tratamientos ortodóncicos con finalidad principalmente estética existirá siempre el riesgo de no cumplir con las expectativas del paciente por motivos dificilmente evitables: imprevisibilidad del crecimiento bucofacial, etc", "Riesgo de que el desarrollo imprevisible de la erupción dentaria, el crecimiento de los maxilares o de respuesta de dientes o hueso a las fuerzas ortodóncicas obliguen a cambiar el plan de tratamiento, requiriendo en ocasiones extracciones de dientes definitivos para conseguir espacio y el alargamiento del tiempo de tratamiento", "Algunos pacientes son mas susceptibles a que se produzca la reabsorción", "acortamiento) de la raíz de uno o varios dientes sometidos a fuerzas ortodóncicas. Este fenómeno es infrecuente, de etiología desconocida pero imprevisible. Habitualmente esto no tiene consecuencias apreciables, pero en ocasiones puede afectar a la longevidad del diente e implicaría alterar el plan de tratamiento", "Riesgo de molestias o dolor en la articulación témporo-mandibular debido a la modificación del patrón oclusal necesario para el correcto alineamiento dental"]}, {"tipo": "parrafo", "texto": "Estos problemas pueden ocurrir con o sin tratamiento de ortodoncia y en general son debidos a factores previos predisponentes (hiperlaxitud ligamentosa, traumatismos previos, artrosis, artritis, bruxismo, stress etc.) y también a un fenómeno de maduración esquelética."}, {"tipo": "lista", "items": ["Riesgo de retracciones de la encía, no previsibles, debidas al efecto de los movimientos dentarios. También pueden aparecer hipertrofiadas como consecuencia del acumulo de placa bacteriana", "Los dientes incluidos tienen un tratamiento mas complejo y sus resultados no se pueden asegurar. Existe la posibilidad que el diente incluido dañe la raíz de los dientes vecinos hasta en ocasiones, provocar su pérdida. En ocasiones el tratamiento falla por anquilosis dental que es imposible diagnosticar previo al tratamiento y que conllevaría la necesidad de extraerlo y reponerlo y estas actuaciones corresponderían a su dentista", "Riesgo de que se produzcan modificaciones en los resultados conseguidos a la conclusión del tratamiento por factores de desarrollo o erupción dentaria, o por modificaciones en el hueso de soporte dental. Estos factores son dificilmente predecibles pero pueden ser paliados siguiendo las indicaciones dadas por el profesional respecto a la utilización de retenedores y a las revisiones una vez terminado el tratamiento"]}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'ORTODONCIA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Los procedimientos propios de la periodoncia van dirigidos al tratamiento de las patologías específicas del sistema de soporte dentario, la enfermedad periodontal, que comprende desde una ligera inflamación de la encía hasta la pérdida de dicho sistema de soporte (formado por la encía, ligamento periodontal, hueso alveolar y cemento radicular) intentando conservar al máximo las estructuras dentarias y su función. La enfermedad periodontal es un proceso de curso crónico en el que intervienen factores infecciosos, hereditarios, inmunológicos, etc. Por tanto la mejoría obtenida mediante el tratamiento nunca se podrá considerar como definitiva porque dependerá del mantenimiento de la higiene por el propio paciente y de otros factores de muy difícil control (inmunológicos, hormonales, etc). Dentro de estos procedimientos propios de la periodoncia se incluyen desde los raspajes y alisados rediculares hasta toda la gama de cirugía periodontal realizada con distintos procedimientos para tratar el hueso, la encía o facilitar los procedimientos higiénicos al paciente. También se incluyen toda una serie de procedimientos de estética gingival. No existe alternativa terapéutica para el tratamiento de esta patología distinta al tratamiento periodontal."}, {"tipo": "titulo", "nivel": 2, "texto": "Factores de riesgo"}, {"tipo": "lista", "items": ["El mal control de placa: sin una correcta técnica de cepillado que elimine los depósitos bacterianos de dientes y encías, el control de la periodontitis no es posible", "El tabaco es un conocido factor agravante de la enfermedad periodontal, por lo que el fumar conlleva una respuesta peor a los tratamientos, y un mayor riesgo de agravamiento de su evolución normal y de reactivación de la enfermedad", "Algunos medicamentos como los anticomiciales, algunos inmunosupresores y los bloqueantes de los canales del calcio, entre otros. Por ello comprendo que es importante comunicar todos los antecedentes clínicos y tratamientos farmacológicos en curso"]}, {"tipo": "titulo", "nivel": 2, "texto": "Cronicidad"}, {"tipo": "parrafo", "texto": "Por todo lo dicho, la enfermedad periodontal no cura (salvo raras excepciones), aunque en la gran mayoría de los casos puede mantenerse detenida mediante tratamiento odontológico si existe una buena cooperación del paciente en el mantenimiento de una buena higiene oral."}, {"tipo": "parrafo", "texto": "En ocasiones no existe más posible tratamiento que la extracción de uno o más dientes, para evitar la propagación de la enfermedad o eliminar la sintomatología de dientes muy afectados."}, {"tipo": "parrafo", "texto": "Además, para poder controlar y frenar la evolución de la enfermedad periodontal es imprescindible, aparte de una cuidadosa higiene oral personal, la realización de visitas periódicas de control y mantenimiento, consistentes en profilaxis (limpiezas) y ocasionales raspados de las irregularidades que los depósitos microbianos provocan en las superficies de las raíces."}, {"tipo": "titulo", "nivel": 2, "texto": "Limitaciones y riesgos"}, {"tipo": "parrafo", "texto": "El/a paciente ha sido informado/a y conoce los riesgos estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico difícilmente previsibles, anestesias prolongadas, daños locales por la punción, excepcionalmente dolores neuropáticos, etc", "Riesgo de aumento de la movilidad dentaria, habitualmente recuperable tras estos tratamientos", "Riesgo de aumento de la sensibilidad dental y de molestias en la zona tratada, también por lo general recuperables ambas. E", "Alteraciones en la estética dentogingival: cualquier tratamiento periodontal, y sobre todo si es quirúrgico y conlleva la eliminación de tejidos enfermos, puede provocar cambios importantes en la estética dental. La alteración más frecuente es la retracción gingival que provoca la sensación de alargamiento de la corona del diente, habitualmente no reversible", "Encaso de cirugía periodontal existen los riesgos específicos de todo procedimiento quirúrgico: dolor, inflamación, hemorragia, hematoma, sobreinfección de la zona, dehiscencia de suturas,", "Riesgo de fracaso de los procedimientos estéticos mucogingivales (de las encías)", "Riesgo de rechazo de los tejidos o materiales injertados (óseos, gingivales, etc)", "Existe siempre el riesgo de reactivación de la enfermedad periodontal que puede deberse a una higiene incompleta o a factores intrínsecos del paciente difícilmente controlables"]}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'PERIODONCIA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "penenenenerenenerenererereveses. ME ha diagnosticado:"}, {"tipo": "lista", "items": ["Patología destructiva dentaria de ……… e.0e0e000e0i 0e DeD DD e e", "Edemtulismo en: ………  A AE E E n"]}, {"tipo": "lista", "items": ["| Coronas =a AA D5 RA A", "Canillaneos.=au-7d aaa N A E E", "Rehabilitación protésica mediante puentes dentosoportados con pilares ………  y pónticos ………"]}, {"tipo": "parrafo", "texto": "Los procedimientos propios de la prótesis fija dentosoportada van dirigidos a la sustitución de los dientes perdidos mediante aparatología que el paciente no puede retirar por sus propios medios. Aunque se intenta conservar al máximo las estructuras dentarias, este tipo de prótesis implica la necesidad de tallar (rebajar) los dientes pilares. Este hecho, a su vez, implica en ocasiones la necesidad de realizar el tratamiento endodóncico (desvitalizar) del diente tallado. La rehabilitación protésica fija tiene como finalidad reponer los dientes ausentes para así reparar la pérdida o disminución de las funciones masticadora y fonatoria, y limitar el defecto estético. Es evidente que la función esperable de una prótesis nunca será la misma que la que proporcionaron los dientes naturales. Las altemativas terapéuticas a los tratamientos de prótesis fija dentosoportada pueden ser de distinto tipo según las características del paciente: prótesis removibles, prótesis fijas implantosoportadas, etc). En este caso concreto la altérnativas terapéuticas:Son: ……… esuecsres re eoó r scaacor eee ceee ElVla paciente ha sido informado/a y conoce los riesgos e inconvenientes estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Riesgos propios de la inyección de anestesia local: posibles hipersensibilidades al anestésico dificilmente previsibles, anestesia prolongada, daños locales por la punción, excepcionalmente dolores neuropáticos, etc", "Problemas de adaptación a la prótesis. Una prótesis fija no deja de ser un cuerpo extraño que se instala en la boca intentando sustituir las funciones dentarias y por lo tanto requerirá un tiempo de adaptación que variará según la situación del paciente y el tipo de prótesis. Requerirá adaptación para la correcta masticación, posibles mordeduras, e hipersalivación en algunos individuos. Estos inconvenientes suelen pasar, pero en algunos pacientes persisten en un grado variable", "Riesgo de no responder a las expectativas estéticas de los pacientes. Es preciso tener claro que estas prótesis, por sus materiales y sistemas de retención nunca podrán igualar la estética de los dientes naturales", "Riesgo de pequeñas zonas de inflamación en la encía de los dientes que soportan la prótesis. La prótesis es un cuerpo extraño y hay que extremar la higiene en toda la zona", "Riesgo de que se introduzcan restos de alimentos bajo los pónticos (pieza que sustituye al diente ausente) de este tipo de prótesis", "Riesgo de que los dientes tallados puedan dar hipersensibilidad, y en ocasiones dolor e infección por daños en la pulpa dentaria (vulgarmente, nervio del diente). Estos daños son propios del tallado y pueden darse inmediatamente después del procedimiento o muy diferido en el tiempo. En caso de producirse se precisaría la endodoncia (desvitalización del diente afectado)", "Riesgo de experimentar sensibilidad exagerada (hiperestesia) durante el periodo de fabricación de las prótesis fijas dentosoportadas (en el que los dientes tallados estarán protegidos con prótesis provisionales), con determinados estímulos, como los cambios de temperatura, dulces, ácidos, fríos, etc., debido a inevitables imperfecciones en el ajuste de dichos provisionales", "Riesgo de que los dientes tallados puedan desarrollar caries en la Zona de terminación de la corona protésica"]}, {"tipo": "parrafo", "texto": "Este proceso es evitable si vigilamos la zona en las revisiones periódicas."}, {"tipo": "lista", "items": ["Riesgo de fractura de los materiales o despegamiento de la prótesis con el paso del tiempo. No hay que olvidar que las prótesis dentarias soportan grandes fuerzas masticatorias, y que esto, irremediablemente, afectará a los materiales y requerirá su sustitución", "Riesgo de que el paciente manifieste o desarrolle algún tipo de intolerancia o alergia a los materiales de los que está construida la prótesis. Esta circunstancia es muy rara, difícilmente previsible, y de difícil solución salvo el cambio de la prótesis", "Siel procedimiento protésico empleado consiste en carillas de porcelana, es preciso señalar el riesgo de que no respondan completamente a las expectativas estéticas de los pacientes. Existe además un riesgo mayor de fracturas y despegamientos de este tipo de prótesis"]}, {"tipo": "parrafo", "texto": "Auinismo el SISIN — ua — ee e rr en ir eo eee ad egLensrer ae teepoticonónictas tererer ael eee toee a DONSUS OSDOCIAJES condiciones personales (-...:::::...mes10a be ii aa ó ss re eee eoe i) PUBE PrEsentar riesgos añadidos consistentes en: El paciente también ha sido informado de que las prótesis fijas dentosoportadas, debido a las fuerzas que soportan y al paso del tiempo, sufrirán deterioros (fisuras, roturas despegamientos, etc) que harán necesario su renovación periódica. Igualmente ha sido informado de que la propia corona protésica facilita la acumulación de placa bacteriana, hecho que puede dañar a dientes y encías, y que deberá ser eliminada mediante una detenida higiene de la prótesis y de los dientes remanentes después de cada comida. Para prevenir estas circunstancias es informado que debe seguir las instrucciones dadas por su dentista y a someterse a revisiones periódicas, en ningún caso espaciadas más de un año, y siempre que tenga cualquier tipo de molestia o duda sobre el tratamiento. Y, DIDÍA ……… —.eontocacronsenaos rcaucoicereo o c N Ne CN e oe ee eee eee COMO PACIENTA (y''El procede"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'PROTESISDENTOSOPORTADA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Los procedimientos propios de la prótesis fija implantosoportada van dirigidos a la sustitución de los dientes perdidos para así reparar la pérdida o disminución de las funciones masticadora y fonatoria, y limitar el defecto estético, mediante aparatología que el paciente no puede retirar por sus propios medios. Este tipo de prótesis va sujeta sobre implantes y en el momento de su colocación han de estar ya osteointegrados. Es evidente que la función esperable de una prótesis nunca será la misma que la que proporcionaron los dientes naturales. La prótesis fija implantosoportada es en la que la estructura protésica puede ir atornillada o cementada sobre unos vástagos (pilares) atornillados, a su vez, a los implantes. Si se trata de prótesis fijas implantosoportadas cementadas, el cemento, generalmente de carácter temporal (para permitir el desmontaje de la prótesis, en caso de aparecer algún tipo de patología periimplantaria, está llamado a experimentar degradación con el paso de un tiempo no excesivo y producir despegamiento de la prótesis, salvo cuando se emplean cementos definitivos, que pueden imposibilitar el levantamiento de la prótesis sin deteriorarla o tener que destruirla. Deberá consultar inmediatamente tan pronto como perciba movimiento en la misma, a fin de proceder a su recementado. Una variante de ésta es la llamada prótesis híbrida que, siendo fija, recuerda a la removible por la presencia de una falsa encía que permite restaurar con un símil de encía los tejidos óseos perdidos por el edentulismo."}, {"tipo": "titulo", "nivel": 2, "texto": "Alternativas terapéuticas"}, {"tipo": "parrafo", "texto": "Las alternativas terapéuticas a los tratamientos de prótesis fija sobre implantes pueden ser de distinto tipo según las características del paciente: prótesis removibles, prótesis fijas dentosoportadas (que implican el tallado o \"rebaje\" de los dientes pilares, etc). En este caso concreto las alternativas terapéuticas son:"}, {"tipo": "titulo", "nivel": 2, "texto": "Limitaciones y riesgos"}, {"tipo": "parrafo", "texto": "EV/la paciente ha sido informado/a y conoce los riesgos e inconvenientes estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Problemas de adaptación a la prótesis. Una prótesis fija no deja de ser un cuerpo extraño que se instala en la boca intentando sustituir las funciones dentarias y por lo tanto requerirá un tiempo de adaptación que variará según la situación del paciente y el tipo de prótesis. Requerirá adaptación para la correcta masticación, posibles mordeduras, e hipersalivación en algunos individuos. Estos inconvenientes suelen pasar, pero en algunos pacientes persisten en un grado variable", "Riesgo de no responder a las expectativas estéticas de los pacientes. Es preciso tener claro que estas prótesis, por sus materiales y sistemas de retención nunca podrán igualar la estética de los: dientes naturales. Este tipo de prótesis precisan, además, espacios para asegurar la posibilidad de una correcta higiene alrededor de los implantes, espacios que pueden afectar a la estética a nivel gingival dejando \"espacios oscuros\" que podrían ser visibles en algunas circunstancias"]}, {"tipo": "parrafo", "texto": "Las prótesis implantosoportadas llamadas prótesis híbridas plantean mayores dificultades para"}, {"tipo": "parrafo", "texto": "conseguir una buena higiene, que, de no realizarse concienzudamente, puede causar halitosis y"}, {"tipo": "parrafo", "texto": "poner en peligro la duración de los implantes."}, {"tipo": "parrafo", "texto": "Además la anchura dentaria vendrá determinada por el diámetro del implante que se haya podido"}, {"tipo": "parrafo", "texto": "utilizar y el ángulo de éste."}, {"tipo": "parrafo", "texto": "Es importante destacar que la pérdida de hueso (reabsorción) que se produce después de la E pérdida del diente propio no se recupera cuando se colocan los implantes y la prótesis fija implantosoportada. El hundimiento que a veces se aprecia en el labio superior, en la zona canina"}, {"tipo": "lista", "items": ["en otras localizaciones debido a la pérdida de hueso, no se solucionará completamente de esta", "Riesgo de pequeñas zonas de inflamación en la encía alrededor de las coronas. La prótesis es un cuerpo extraño y hay que extremar la higiene en toda la zona, en especial si por motivos estéticos la corona se sitúa parcialmente subgingival", "Riesgo de que se introduzcan restos de alimentos bajo la prótesis o en los espacios vacíos que debe respetar", "Riesgo de fractura de los materiales o despegamiento o aflojamiento de los sistemas de retención de la prótesis con el paso del tiempo. No hay que olvidar que las prótesis dentarias soportan grandes fuerzas masticatorias, y que esto, irremediablemente, afectará a los materiales y requerirá su sustitución", "Riesgo de que el paciente manifieste o desarrolle algún tipo de intolerancia o alergia a los materiales de los que está construida la prótesis. Esta circunstancia es muy rara, difícilmente previsible, y de difícil solución salvo la sustitución de la prótesis"]}, {"tipo": "parrafo", "texto": "Asimismo el St/STa ……… cmreereenceee eee eee eee eeeeees=..POL SUS ESPeciales condiciones personales ( ……… <.--.<i.-ecicai o e e e N É I ee s) PUEdE Presentar riesgos añadidos consistentes en: El paciente también ha sido informado de que las prótesis fijas implantosoportadas, debido a las fuerzas que soportan y al paso del tiempo, sufrirán deterioros (fisuras, roturas, despegamientos, etc) que harán necesario su renovación periódica. Igualmente ha sido informado de que la propia prótesis facilita la acumulación de placa bacteriana, hecho que puede dañar las encías, y que deberá ser eliminada mediante una detenida higiene de la prótesis y de los dientes remanentes después de cada comida. Para prevenir estas circunstancias se le informa que debe seguir las instrucciones dadas por su dentista y a someterse a revisiones periódicas, en ningún caso espaciadas más seis meses, y siempre que tenga cualquier tipo de molestia o duda sobre el tratamiento. Estas revisiones pueden implicar la necesidad de desmontar la prótesis para su completa higiene y reajuste."}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'PROTESISIMPLANTOSOPORTADA' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Los procedimientos propios de la prótesis removible van dirigidos a la sustitución de los dientes perdidos mediante aparatología no fija, susceptibles de ser retirados de la boca a voluntad del propio paciente y en cualquier momento, teniendo como finalidad la reparación de la pérdida o disminución de las funciones de masticación y fonación, y limitar el defecto estético."}, {"tipo": "parrafo", "texto": "Esta aparatología removible consta de dientes artificiales que se sujetan sobre una base acrílica, metálica y/o flexible. Dicha estructura base, a su vez, se apoya sobre la encía y se sujeta a dientes remanentes, si es que existen, mediante retenedores directos (vulgarmente conocidos como \"ganchos\") o retenedores indirectos (ataches)."}, {"tipo": "parrafo", "texto": "Es evidente que la función esperable de una prótesis nunca será la misma que la que proporcionaron los dientes naturales. Dentro de estos procedimientos se incluyen las prótesis parciales y las prótesis completas de cualquiera de las dos arcadas"}, {"tipo": "parrafo", "texto": "Se han sopesado y descartado por distintos motivos de los que ha sido informado/a otros procedimientos terapéuticos AlEMAtIVOS COMO +.:-200:-.=5> e=e conersnano o A ANAN AA AR ElVla paciente ha sido informado/a y conoce los riesgos e inconvenientes estadísticamente frecuentes que puede comportar este tratamiento:"}, {"tipo": "lista", "items": ["Problemas de adaptación a la prótesis. Una prótesis removible no deja de ser un cuerpo extraño que se instala en la boca intentando sustituir las funciones dentarias y por lo tanto requerirá un tiempo de adaptación que variará según la situación del paciente y el tipo de prótesis. Requerirá adaptación para la correcta pronunciación, masticación y deglución, posibles nauseas, mordeduras, disminución del sentido del gusto y sequedad de boca. Estos inconvenientes suelen pasar, pero en algunos pacientes persisten en un grado variable", "Riesgo de no responder a las expectativas estéticas de los pacientes. Es preciso tener claro que estas prótesis, por sus materiales nunca podrán igualar el tono y brillo exactos de los dientes naturales originales del paciente"]}, {"tipo": "parrafo", "texto": "Además, en el caso de las prótesis parciales, los sistemas de retención o \"ganchos\" pueden generar aspectos inestéticos en Zonas visibles de la boca."}, {"tipo": "lista", "items": ["Riesgo de aparición de llagas y rozaduras en partes blandas, sobre todo al principio, y que requerirían pequeños retoques por parte del dentista", "Riesgo de aparición de problemas de movilidad de la prótesis, en especial si no hay dientes o si el hueso alveolar está muy reabsorbido, como ocurre con frecuencia en la prótesis completa inferior", "Riesgo de que los ganchos y retenedores de la prótesis dañen los dientes de soporte con el paso del tiempo", "Riesgo de que el paciente manifieste o desarrolle algún tipo de intolerancia o alergia a los materiales de los que está construida la prótesis. Esta circunstancia es, difícilmente previsible, de difiícil solución, y puede obligar a la sustitución de la prótesis por otra realizada en otros materiales", "Respecto a la masticación, estas estructuras móviles nunca podrán sustituir a los dientes originales. Su capacidad de corte y trituración es menor y la fuerza que podemos ejercer sobre este tipo de prótesis también es menor que la que podíamos ejercer sobre los dientes naturales"]}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'PROTESISREMOVIBLE' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Asociación Española de"}, {"tipo": "titulo", "nivel": 2, "texto": "Aee endodoncia"}, {"tipo": "titulo", "nivel": 2, "texto": "Documento de información al paciente"}, {"tipo": "titulo", "nivel": 2, "texto": "Sobre reendodoncia"}, {"tipo": "parrafo", "texto": "Características del procedimiento: ¿En qué consiste? Consiste en la eliminación de los materiales que se encuentran en el interior de los con ductos radiculares de un diente y la posterior limpieza, conformación y relleno de dichos conductos. ¿Para qué sirve? Es una intervención que se realiza cuando una endodoncia no tenido éxito, para intentar conservar el diente en el lugar que ocupa en la arcada dentaria, manteniendo una fun- = ciónadecuada."}, {"tipo": "lista", "items": ["¿Cómosehace? = Trasanestesiar localmente la zona, se realiza una cavidad para acceder al interior del diente. = Luego se eliminan los materiales,de relleno.utilizados enJa.endodoncia previa, se limpian < los conductos radiculares y se rellenan con un material adecuado. Finalmente se coloca z Unempaste provisional que deberá ser sustituido por uno definitivo. Será necesario el uso = deradiografías dentales intraorales para realizar elkprocedimiento. Dependiendo del estado -. previo del diente y de la anatomía que presente, pueden ser necesarias una o más sesiones"]}, {"tipo": "parrafo", "texto": "Riesgos y complicaciones: Cualquier intervención en un paciente conlleva riesgos. La mayor parte de las veces no se presentan complicaciones, pero a veces sí, por lo que es importante que estas se co nozcan. Las más frecuentes son: A) Referidas al uso de anestésicos locales: Interrupción de la función sensitiva (sensación de hormigueo) generalmente de forma tem poral, ulceración en la mucosa, aparición de hematomas y alteraciones generalmente tran sitorias como bloqueo de la articulación temporomandibular, crisis vaso-vagal consistente en sudoración fría, sensación de mareo, bajada de tensión arterial e incluso lipotimia. En el caso de existir alguna alergia conocida a los anestésicos debe avisar siempre al profesional. Si hubiera alguna alergia desconocida pueden producirse alteraciones del tipo urticaria, edema de glotis e incluso shock anafiláctico, que necesitarían otros me dios de reanimación. B) Referidas al tratamiento en sí: Durante la fase de apertura y limpieza de los conductos pueden aparecer alteraciones no detectables que imposibiliten la continuación del tratamiento de conductos tales como: existencia de una red compleja de curvaturas o calcificaciones imposibles de trabajar con los instrumentos disponibles actualmente, comunicaciones con los tejidos periodontales, C/ Cochabamba, 24 Bajo B Madrid 28016 España T. 629 605 613 aedeQaede.info 1/3"}, {"tipo": "parrafo", "texto": "A E D E Asociación Española de"}, {"tipo": "titulo", "nivel": 2, "texto": "— = endodoncia"}, {"tipo": "lista", "items": ["bien contratiempos como la fractura de algún instrumento que el profesional intentará subsanar, pero que en el caso de no lograrse complicarían el pronóstico del tratamiento"]}, {"tipo": "parrafo", "texto": "C) Referidas al futuro del tratamiento: Una vez finalizado el tratamiento es necesario realizar la restauración definitiva del dien te. Si dicha reconstrucción no fuese la indicada o se retrasase en exceso o el paciente tu viera hábitos de apretamiento (bruxismo) o mordiese accidentalmente alimentos muy duros sobre los dientes desvitalizados, podrían producirse fisuras verticales o fracturas radiculares que empeorarían el pronóstico restaurador, pudiendo llegar a implicar la ne cesidad de extraer el diente. Una vez terminado el tratamiento (o entre las sesiones) el diente puede quedar sensi bilizado a la presión durante un periodo más o menos largo pudiendo necesitar algún analgésico. En algunos casos, puede llegar a producirse la inflamación de los tejidos próximos al diente, pudiendo ser necesaria en tal caso la administración de antibióticos. ... Podrán ser necesarias revisiones y radiografías algún tiempo después de realizar el tra S. tamiento para comprobar su evolución y pronóstico definitivo. Puede producirse algún =. cambio de coloración externa en la corona o bien necesitar algún otro procedimiento £ comoelretratamiento no quirúrgico o la cirugía periapical, si con el primer tratamiento = noseconsiguiesen los objetivos, ya que en el organismo humano nunca podemos tener"}, {"tipo": "lista", "items": ["apriori la garantía absoluta del éxito"]}, {"tipo": "parrafo", "texto": "% Riesgos personalizados: -. Sehará siempre una historia clínica de las enfermedades que afecten al paciente para =. comprobar la idoneidad del retratamiento de conductos (reendodoncia). Información de su interés: Usted tiene derecho a conocer el procedimiento dental al que va a ser sometido y los riesgos y complicaciones más frecuentes que pueden ocurrir. En su actual esta do clínico, los beneficios derivados de la realización de este tratamiento superan los posibles riesgos. Por este motivo se le indica la conveniencia de que le sea practica do. Si aparecieran complicaciones, el personal médico que le atiende está capaci tado y dispone de medios para tratar de resolverlas. Por favor, lea atentamente este documento y consulte con su dentista las dudas que pueda tener. Alternativas al procedimiento: La extracción del diente. C/ Cochabamba, 24 Bajo B Madrid 28016 España T. 629 605 613 aedeQaede.info 2/3"}, {"tipo": "parrafo", "texto": "Asociación Española de AEDE ENDODoncIA www.aede.info"}, {"tipo": "titulo", "nivel": 2, "texto": "Consentimiento informado — reendodoncia"}, {"tipo": "parrafo", "texto": "Para satisfacción de los derechos del paciente, como instrumento favorecedor del correcto uso de los Procedimientos Terapéuticos y Diagnósticos, y en cumplimiento de la Ley General de Sanidad y la ley 41/2002: N ae CO faloe-tel-T a Mo) D/D? ssc a6EZÉ COMO:SUrepresentante legal en pleno uso de mis facultades, libre y voluntariamente, DECLARO: OQueeUlalbr/Dra =. = —. A NA me ha explicado, en términos asequibles, que necesito un retratamiento endodóntico en el/los diente/s ……… w..mmmenerenenees.. Y ME han Sido expuesto los posibles riesgos gene rales contenidos en las hojas informativas adjuntas, publicadas por la Asociación Espa ñola de Endodoncia (AEDE), permitiéndome realizar todas las observaciones y pregun tas para aclarar mis dudas."}, {"tipo": "lista", "items": ["Riesgos personalizados en su caso:", "Consiento en que se tomen fotografías oregistrosen.etros tipos de soporte audio z visual, antes, durante y después de la intervención quirÚúrgica, para facilitar el avance del", "conocimiento científico y la docencia. En todos los casos será resguardada la identidad del paciente"]}, {"tipo": "parrafo", "texto": "Manifiesto que estoy satisfecho con la información recibida y que comprendo el alcance y los riesgos del tratamiento."}, {"tipo": "parrafo", "texto": "También comprendo que, en cualquier momento y sin necesidad de dar ninguna explicación, puedo revocar el consentimiento que ahora presto."}, {"tipo": "parrafo", "texto": "Y entales condiciones CONSIENTO en que se merealice el retratamiento endodóntico. TTO 740 Mim 0 Firma del paciente: Firma del profesional:"}, {"tipo": "parrafo", "texto": "Edo: D/DA uuaa TA Edo: D/D2 ru e a BN|c ONO ann rec C/ Cochabamba, 24 Bajo B Madrid 28016 España T. 629 605 613 aedeQaede.info 3/3"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'REENDO' and version = 1;

update consent_plantillas
   set composicion = '[{"ref": "preambulo"}, {"ref": "identificacion"}, {"ref": "representante"}, {"ref": "diagnostico_plan"}, {"nodos": [{"tipo": "parrafo", "texto": "Firma del paciente o de su representante Fecha Declaro que he conversado acerca de los riesgos, beneficios, consecuencias y alternativas al injerto óseo y gingival con (nombre del paciente), quien tuvo la oportunidad de hacer preguntas y que, a mi entender, mi paciente comprende lo que se le ha explicado. Firma del dentista Fecha Firma del testigo Fecha"}, {"tipo": "parrafo", "texto": "Nombre del paciente: Fecha:"}, {"tipo": "titulo", "nivel": 2, "texto": "Diagnostico"}, {"tipo": "parrafo", "texto": "iniciales del paciente Se me ha informado que tengo problemas y/o una enfermedad periodontales (de las encías y el hueso), que deben tratarse quirúrgicamente, lo cual incluye injertos óseos y técnicas para la regeneración ósea. Entiendo que el objetivo de este procedimiento, en forma conjunta con la cirugía con colgajo periodontal (de la encía), es el de permitir el acceso para eliminar las bacterias, mediante la limpieza de las raíces dentales y del recubrimiento de la encía. También puede tratar irregularidades del maxilar, si las hubiera, mediante el uso de un material de injerto óseo, para que cuando la encía se reemplace alrededor de la pieza dental, permita la reducción de cavidades, infección e inflamaciones y puede mejorar la cicatrización ósea. La reducción en la profundidad de las cavidades de las encías puede mejorar la facilidad y efectividad de mi higiene oral personal y la aptitud de un profesional odontológico para optimizar la limpieza de mi dentadura. Al reducirse la infección y la inflamación puede minimizarse todavía más la pérdida del hueso y del tejido de las encías que sustentan la dentadura, lo cual puede contribuir a una retención más duradera de mis piezas dentales en la o las áreas operadas. Después de que la anestesia aplicada mediante una inyección haya insensibilizado el área a operar, la encía se reflecta (se le practica una incisión durante la cirugía) para exponer las raíces de la pieza dental, las cuales se limpian y alisan. Antes de colocar el material del injerto en la o las áreas, pueden aplicarse antibióticos y/u otros productos químicos a las raíces para descontaminarlas. Se me ha informado que los injertos óseos pueden llevarse a cabo en áreas de mi boca asociadas con zonas de las encías donde haya cavidades y/o recesiones. También se me ha explicado que éste es un procedimiento que puede implicar el injerto quirúrgico del hueso, mediante la extracción de uno o más trozos de hueso de otra región de mi cuerpo, lo cual requiere otro sitio quirúrgico o el uso de otro material óseo comercial, proveniente de otro ser humano o de un animal. El material del injerto se puede usar en forma de bloque, sobre una zona grande, o en forma de material en partículas, para las áreas de menor tamaño. Admito que he tenido la oportunidad de conversar acerca de estas opciones y, a mi elección, con mi dentista, antes de prestar el consentimiento para este tratamiento, procedimiento"}, {"tipo": "parrafo", "texto": "Beneficios de los injertos óseos y/o de la cirugía regenerativa, no limitados a los siguientes: El objetivo de los injertos óseos y/o de la cirugía regenerativa es el de lograr que el hueso vuelva a \"crecer\", para permitir posiblemente la colocación de un implante dental, ya sea durante esta misma cirugía o en una fecha posterior. Por otro lado, el propósito de esta cirugía puede ser el de contribuir a crear una cresta alveolar restaurable, para mejorar la estética y la función en el lugar donde irá una pieza dental de reemplazo (artificial) como parte de un puente dental."}, {"tipo": "parrafo", "texto": "Riesgos de los injertos óseos y/o de la cirugía regenerativa, no limitados a los siguientes:"}, {"tipo": "parrafo", "texto": "Entiendo que con la cirugía puede haber sangrado posoperatorio, inflamación, dolor, infección, decoloración facial, sensibilidad temporal 0, en ocasiones permanente, en la dentadura al calor, al frío, a los dulces o a las comidas ácidas. Puede presentarse un adormecimiento temporal o permanente de las áreas quirúrgicas que me afecten los labios, el mentón y la lengua, distorsionando posiblemente el sentido del gusto. Entiendo que puedo ver cambios en el aspecto de mis encías. Puede haber una posición diferente en las raíces o espacios entre las piezas dentales de mayor tamaño. También entiendo que puede ser necesario un segundo procedimiento si la cirugía inicial no es completamente exitosa. Entiendo que recibiré un anestésico local mediante una inyección y/u otras medicaciones. En raras ocasiones, los pacientes pueden sufrir una reacción fuerte e impredecible al anestésico, lo cual puede requerir atención médica de emergencia. La medicación puede afectar la capacidad de controlar la deglución. Esto aumenta las posibilidades de tragar objetos extraños durante el tratamiento. Según la anestesia y las medicaciones administradas, es probable que necesite que un conductor que yo designe me transporte a mi casa. Rara vez, como resultado de una inyección, puede haber una lesión nerviosa, temporaria o permanente, que derive en la pérdida de sensibilidad en el mentón, los labios, las encías, la lengua y en una pérdida parcial del sentido del gusto. Entiendo que el hecho de mantener la boca abierta durante el tratamiento puede dejarme una sensación temporaria de rigidez y dolor en la mandíbula y que puede dificultarme abrir bien la boca durante varios días. En ocasiones, esto puede ser una indicación de otro problema. Debo notificar a este consultorio si se presenta esta inquietud respecto de la función mandibular o de otra índole. Entiendo que todas las medicaciones tienen el potencial de acarrear riesgos, efectos secundarios e interacciones medicamentosas. Por lo tanto, es crucial que informe a mi dentista acerca de todas las medicaciones y suplementos que esté tomando actualmente, los cuales son: Entiendo que el hecho de fumar y/o masticar tabaco y/o consumir alcohol puede afectar las posibilidades de que las encías y/o los huesos me cicatricen normalmente y limitar el potencial de un resultado satisfactorio de mi cirugía. Estoy de acuerdo en seguir las instrucciones de mi dentista en lo que se refiere al cuidado diario de mi boca, dentadura y encías. Alternativas al tratamiento sugerido: Entiendo que las alternativas al injerto óseo y/o a la cirugía regenerativa incluyen: no recibir tratamiento, no proceder al raspado radicular quirúrgico y al recubrimiento de la encía (raspado y alisado periodontal), con o sin medicación, en un intento por reducir aún más las bacterias y el sarro que se encuentra debajo del margen gingival, los puentes dentales, las dentaduras parciales removibles, y no reemplazar piezas dentales. Alternativas analizadas: Ninguna persona me ha dado garantía o certeza alguna respecto de que el tratamiento o la cirugía propuestos servirán para curar o mejorar la o las afecciones indicadas con anterioridad. Marque sólo una de las siguientes casillas que se aplique a su caso: Me niego a otorgar mi consentimiento para el tratamiento propuesto, según se describió anteriormente y entiendo las consecuencias potenciales vinculadas con esta negativa. He tenido la oportunidad de hacer preguntas y otorgo mi consentimiento para el tratamiento propuesto, según se describió anteriormente. Injerto óseo"}]}, {"ref": "riesgos_personalizados"}, {"ref": "contraindicaciones"}, {"ref": "declaracion"}, {"ref": "revocacion"}, {"ref": "proteccion_datos"}, {"ref": "lugar_fecha"}, {"ref": "firmas_paciente"}]'::jsonb
 where codigo = 'REGENERACION' and version = 1;


commit;

-- Comprobación: no debe devolver ninguna fila.
select p.codigo, nodo->>'texto' as andamiaje_duplicado
  from consent_plantillas p,
       lateral jsonb_array_elements(p.composicion) item,
       lateral jsonb_array_elements(coalesce(item->'nodos','[]'::jsonb)) nodo
 where nodo->>'texto' ilike 'Para dicho diagn%'
    or nodo->>'texto' ilike 'En relaci%n con el diagn%';
